package com.primehr.learningdevelopment.participation.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="ld_training_order_source",uniqueConstraints={@UniqueConstraint(name="uk_ld_training_order_offering",columnNames={"agency_id","offering_id"}),@UniqueConstraint(name="uk_ld_training_order_number",columnNames={"agency_id","normalized_order_number"})})
public class LdTrainingOrderSource extends RspAuditedEntity {@Column(name="offering_id",nullable=false,length=36)private String offeringId;@Column(name="offering_version",nullable=false)private int offeringVersion;@Column(name="offering_fingerprint",nullable=false,length=64)private String offeringFingerprint;@Column(name="order_number",nullable=false,length=100)private String orderNumber;@Column(name="normalized_order_number",nullable=false,length=100)private String normalizedOrderNumber;@Column(nullable=false,length=1000)private String subject;@Column(name="attendance_directive",nullable=false,length=3000)private String attendanceDirective;@Column(name="dress_code",length=1000)private String dressCode;@Column(length=2000)private String notes;@Column(name="approved_by",nullable=false,length=100)private String approvedBy;@Column(name="approved_at",nullable=false)private Instant approvedAt;@Column(name="snapshot_fingerprint",nullable=false,length=64)private String snapshotFingerprint;protected LdTrainingOrderSource(){}public LdTrainingOrderSource(String agency,String offering,int version,String offeringFingerprint,String number,String subject,String directive,String dressCode,String notes,String actor,Instant at,String fingerprint){super(agency);offeringId=requiredText(offering,"offeringId");offeringVersion=version;this.offeringFingerprint=requiredText(offeringFingerprint,"offeringFingerprint");orderNumber=requiredText(number,"orderNumber");normalizedOrderNumber=orderNumber.toUpperCase(java.util.Locale.ROOT);this.subject=requiredText(subject,"subject");attendanceDirective=requiredText(directive,"attendanceDirective");this.dressCode=optionalText(dressCode);this.notes=optionalText(notes);approvedBy=requiredText(actor,"actor");approvedAt=at;snapshotFingerprint=requiredText(fingerprint,"snapshotFingerprint");}public String getOfferingId(){return offeringId;}public int getOfferingVersion(){return offeringVersion;}public String getOfferingFingerprint(){return offeringFingerprint;}public String getOrderNumber(){return orderNumber;}public String getSubject(){return subject;}public String getAttendanceDirective(){return attendanceDirective;}public String getDressCode(){return dressCode;}public String getNotes(){return notes;}public String getApprovedBy(){return approvedBy;}public Instant getApprovedAt(){return approvedAt;}public String getSnapshotFingerprint(){return snapshotFingerprint;}}
